css='''
/* Versão 21: envio obrigatório da lição */
.lessonSubmitCard{margin:26px 0 8px;padding:20px;border-radius:22px;background:linear-gradient(135deg,#f6fff9 0%,#f7fbff 100%);border:1px solid #cfe6d7;box-shadow:0 12px 30px rgba(39,79,55,.08)}.lessonSubmitHeader{display:flex;gap:12px;align-items:flex-start}.lessonSubmitIcon{width:46px;height:46px;border-radius:14px;display:grid;place-items:center;background:#e4f6ea;font-size:23px;flex:0 0 auto}.lessonSubmitHeader h4{margin:0 0 4px;font-size:19px;color:#20342a}.lessonSubmitHeader p{margin:0;color:#627168;line-height:1.55;font-size:13px}.lessonSubmitProgress{margin:16px 0 12px;padding:11px 13px;border-radius:14px;background:#fff;border:1px solid #dfeae3;font-weight:850;color:#40534a}.lessonSubmitProgress.ready{background:#eef9f2;color:#24653d;border-color:#c8e7d2}.lessonSubmitProgress.sent{background:#e4f6ea;color:#17683a;border-color:#bfe3cb}.lessonProfile{display:grid;grid-template-columns:1fr 1.2fr;gap:10px;margin-top:14px}.lessonField{display:flex;flex-direction:column;gap:6px}.lessonField label{font-size:12px;font-weight:900;color:#53655b}.lessonField input{width:100%;border:1px solid #d8e3dc;border-radius:12px;padding:11px 12px;background:#fff;font:inherit;color:#24322b;outline:none}.lessonField input:focus{border-color:#91c7a5;box-shadow:0 0 0 3px rgba(67,157,92,.12)}.lessonSubmitActions{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-top:14px}.lessonSubmitBtn{display:inline-flex;align-items:center;justify-content:center;gap:8px;border:0;border-radius:14px;padding:12px 16px;font-weight:950;background:linear-gradient(135deg,var(--green) 0%,var(--greenDark) 100%);color:#fff;box-shadow:0 9px 20px rgba(31,126,69,.18)}.lessonSubmitBtn:disabled{opacity:.44;box-shadow:none;cursor:not-allowed}.lessonSubmitHint{font-size:12px;line-height:1.5;color:#69766f}.lessonSubmitResult{display:none;margin-top:12px;padding:11px 13px;border-radius:13px;font-size:13px;font-weight:800;line-height:1.5}.lessonSubmitResult.show{display:block}.lessonSubmitResult.success{background:#e7f7ec;border:1px solid #c5e8d0;color:#1f6b3b}.lessonSubmitResult.error{background:#fff0f0;border:1px solid #efcccc;color:#922f2f}.lessonSubmitResult.info{background:#eef6ff;border:1px solid #cfe1f5;color:#315a7c}.lessonSentBadge{display:inline-flex;margin-top:8px;padding:5px 8px;border-radius:999px;background:#e4f6ea;color:#17683a;border:1px solid #bfe3cb;font-size:11px;font-weight:950}@media(max-width:720px){.lessonProfile{grid-template-columns:1fr}.lessonSubmitBtn{width:100%}.lessonSubmitActions{align-items:stretch}}
'''
