js=r'''
// Versão 21: fechamento obrigatório de cada lição
const V21_PROFILE_STUDENT=PREFIX+'profile:studentName';
const V21_PROFILE_EMAIL=PREFIX+'profile:recipientEmail';
const V21_ENDPOINT='https://fkxwlezflfpdrronluci.supabase.co/functions/v1/enviar-licao-lousa';
const V21_ANON='eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImZreHdsZXpmbGZwZHJyb25sdWNpIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODc1MjA1ODMsImV4cCI6MjEwMzA5NjU4M30.xnWcCwgR9bJ2MBB9seK4eF_KcDv6ZRxFwUZ-dN1sv2k';
function v21LessonKey(lesson,suffix){return PREFIX+'lesson:'+(currentSubjectKey||'geral')+':'+lesson.key+':'+suffix}
function v21LessonSent(lesson){return localStorage.getItem(v21LessonKey(lesson,'sent'))==='1'}
function v21ValidEmail(v){return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(v||'').trim())}
function v21DownloadPdf(base64,filename){try{const b=atob(base64),u=new Uint8Array(b.length);for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);const blob=new Blob([u],{type:'application/pdf'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename||'lousa_de_estudos.pdf';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2500)}catch(e){console.error(e)}}
function v21Payload(lesson,name,email){const subject=subjects[currentSubjectKey]||{};let correctCount=0;const answers=lesson.questions.map((q,i)=>{if(q.type==='mcq'){const c=getChoice(q),n=c===null?null:Number(c),ok=String(c)===String(q.correct);if(ok)correctCount++;return{number:i+1,question:q.text,type:'mcq',answer:n===null?'':(q.options[n]||''),correct:ok}}return{number:i+1,question:q.text,type:'handwritten',handwriting:getCanvas(q)||''}});return{subjectKey:currentSubjectKey,subjectTitle:subject.title||currentSubjectKey,lessonKey:lesson.key,lessonTitle:lesson.title,studentName:name,recipientEmail:email,totalQuestions:lesson.questions.length,completedCount:topicDoneCount(lesson),correctCount,completedAt:new Date().toLocaleString('pt-BR'),answers}}
function v21SubmissionCard(lesson){const w=document.createElement('section');w.className='lessonSubmitCard';w.innerHTML=`<div class="lessonSubmitHeader"><div class="lessonSubmitIcon">📤</div><div><h4>Finalizar e enviar esta lição</h4><p>Para liberar a próxima lição, todas as questões precisam estar concluídas e o PDF precisa ser enviado para o e-mail cadastrado.</p></div></div><div class="lessonSubmitProgress"></div><div class="lessonProfile"><div class="lessonField"><label>Nome do aluno</label><input class="studentNameInput" type="text" autocomplete="name" placeholder="Digite o nome"></div><div class="lessonField"><label>E-mail que receberá o PDF</label><input class="recipientEmailInput" type="email" inputmode="email" autocomplete="email" placeholder="exemplo@email.com"></div></div><div class="lessonSubmitActions"><button class="lessonSubmitBtn" type="button">📨 Enviar todas as respostas</button><span class="lessonSubmitHint">O PDF também será salvo automaticamente no aparelho.</span></div><div class="lessonSubmitResult" role="status"></div>`;const p=w.querySelector('.lessonSubmitProgress'),n=w.querySelector('.studentNameInput'),e=w.querySelector('.recipientEmailInput'),b=w.querySelector('.lessonSubmitBtn'),r=w.querySelector('.lessonSubmitResult');n.value=localStorage.getItem(V21_PROFILE_STUDENT)||'';e.value=localStorage.getItem(V21_PROFILE_EMAIL)||'';let busy=false;const msg=(t,k='info')=>{r.textContent=t;r.className='lessonSubmitResult show '+k};function refresh(){const done=topicDoneCount(lesson),total=lesson.questions.length,sent=v21LessonSent(lesson),okName=n.value.trim().length>0,okMail=v21ValidEmail(e.value);p.className='lessonSubmitProgress'+(sent?' sent':done===total?' ready':'');p.textContent=sent?'✓ Lição finalizada e enviada. A próxima etapa está liberada.':done===total?'Tudo respondido. Agora falta enviar a lição para finalizar.':`${done} de ${total} questões concluídas. Responda todas antes de enviar.`;b.disabled=busy||sent||done!==total||!okName||!okMail;b.textContent=sent?'✓ Lição enviada':busy?'Enviando e criando PDF...':'📨 Enviar todas as respostas';if(!sent&&done===total&&(!okName||!okMail))msg('Preencha o nome do aluno e um e-mail válido para liberar o envio.','info')}function save(){localStorage.setItem(V21_PROFILE_STUDENT,n.value.trim());localStorage.setItem(V21_PROFILE_EMAIL,e.value.trim().toLowerCase());refresh()}n.addEventListener('input',save);e.addEventListener('input',save);b.addEventListener('click',async()=>{if(b.disabled||busy)return;busy=true;refresh();msg('Preparando o PDF e enviando as respostas...','info');const payload=v21Payload(lesson,n.value.trim(),e.value.trim().toLowerCase());try{const res=await fetch(V21_ENDPOINT,{method:'POST',headers:{'Content-Type':'application/json','apikey':V21_ANON,'Authorization':'Bearer '+V21_ANON},body:JSON.stringify(payload)}),data=await res.json().catch(()=>({}));if(data.pdfBase64)v21DownloadPdf(data.pdfBase64,data.filename);if(res.ok&&data.emailSent){localStorage.setItem(v21LessonKey(lesson,'sent'),'1');localStorage.setItem(v21LessonKey(lesson,'sentAt'),new Date().toISOString());localStorage.setItem(v21LessonKey(lesson,'sentEmail'),payload.recipientEmail);msg('✓ PDF salvo e enviado por e-mail. A próxima lição foi liberada.','success');toast('Lição enviada com sucesso!');updateProgress()}else if(res.ok&&data.emailConfigured===false){msg('O PDF foi criado e salvo, mas o serviço de e-mail ainda precisa ser conectado. A próxima lição continua bloqueada.','error')}else msg(data.message||data.error||'O PDF foi criado, mas o envio por e-mail falhou. Tente novamente.','error')}catch(err){console.error(err);msg('Não foi possível enviar agora. Verifique a internet e tente novamente.','error')}finally{busy=false;refresh()}});const onChange=()=>refresh();window.addEventListener('lousaProgressChanged',onChange);activeBoardCleanups.push(()=>window.removeEventListener('lousaProgressChanged',onChange));refresh();return w}
const v21UpdateProgress=updateProgress;updateProgress=function(){v21UpdateProgress();window.dispatchEvent(new CustomEvent('lousaProgressChanged'))};
isLessonUnlocked=function(index){if(index===0)return true;return v21LessonSent(lessons[index-1])};
renderTopicCards=function(){const grid=document.getElementById('topicGrid');grid.innerHTML='';lessons.forEach((lesson,index)=>{const unlocked=isLessonUnlocked(index),btn=document.createElement('button');btn.type='button';btn.className='topicCard'+(lesson.finalChallenge?' finalChallenge':'')+(unlocked?'':' locked');btn.dataset.topic=lesson.key;const previous=index>0?lessons[index-1]:null,previousTitle=previous?previous.title:'',ready=previous&&topicDoneCount(previous)===previous.questions.length;btn.innerHTML=`${unlocked?'':`<span class="lockBadge">🔒</span>`}<span class="topicEmoji">${lesson.emoji}</span><strong>${lesson.title}</strong><span class="sub">${lesson.subtitle}</span>${lesson.finalChallenge?'<span class="finalBadge">🏆 ETAPA FINAL</span>':''}<span class="topicProgress">${topicDoneCount(lesson)} de ${lesson.questions.length} concluídas</span>${v21LessonSent(lesson)?'<span class="lessonSentBadge">✓ Lição enviada</span>':''}${unlocked?'':`<span class="lockedMessage">${ready?'Envie':'Conclua'} ${previousTitle} para liberar</span>`}`;if(unlocked)btn.addEventListener('click',()=>openTopic(lesson.key));else{btn.disabled=true;btn.setAttribute('aria-label',`${lesson.title} bloqueada. ${ready?'Envie':'Conclua'} ${previousTitle} primeiro.`)}grid.appendChild(btn)})};
const v21RenderLesson=renderLesson;renderLesson=function(lesson){v21RenderLesson(lesson);document.getElementById('lessonContent').appendChild(v21SubmissionCard(lesson))};
'''
if 'const V21_PROFILE_STUDENT' not in s:
    marker='showSubjects();\n</script>'
    if marker not in s: raise SystemExit('Final do script não encontrado')
    s=s.replace(marker,js+'\nshowSubjects();\n</script>',1)
